import manifest from "./cocktail-illustrations.json";

/** Generated by scripts/sync-cocktail-illustrations.ts; missing assets never enter the manifest. */
export const cocktailIllustrations: Record<string, { asset: string; mode: string }> = manifest;

const aliases: Record<string, string> = {
  "whisky-sour": "whiskey-sour",
  "highball": "whisky-highball",
  "whiskey-highball": "whisky-highball",
  "cv-vodka-orange-juice": "vodka-orange",
  "long-island": "long-island-iced-tea",
  "espresso-martini": "espresso-martini-classic",
};

export function getCocktailIllustration(id: string): string | undefined {
  const normalized = id.replace(/^classic-original-/, "").replaceAll("_", "-");
  const key = Object.hasOwn(cocktailIllustrations, normalized) ? normalized : aliases[normalized];
  const entry = key && Object.hasOwn(cocktailIllustrations, key) ? cocktailIllustrations[key] : undefined;
  return entry ? `/images/cocktails/illustrated/${entry.asset}.png` : undefined;
}
